import{_ as o,o as r,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"品牌视觉的趋同：2010 年代以来大公司 logo 为什么越来越像","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/design/logo-convergence.md","filePath":"topics/design/logo-convergence.md"}'),a={name:"topics/design/logo-convergence.md"};function d(s,t,i,g,l,u){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="品牌视觉的趋同-2010-年代以来大公司-logo-为什么越来越像" tabindex="-1">品牌视觉的趋同：2010 年代以来大公司 logo 为什么越来越像 <a class="header-anchor" href="#品牌视觉的趋同-2010-年代以来大公司-logo-为什么越来越像" aria-label="Permalink to &quot;品牌视觉的趋同：2010 年代以来大公司 logo 为什么越来越像&quot;">​</a></h1><blockquote><p>来源：en.wikipedia ⟪Gap Inc.⟫、⟪Airbnb⟫、⟪Google logo⟫、⟪Starbucks⟫、⟪Burberry⟫、⟪Intel⟫、⟪Mastercard⟫、⟪X (social network)⟫、⟪Blanding⟫（消歧义页）；一手设计方：Pentagram case study（Mastercard / Warner Bros.）；专业媒体：Reuters、GQ、The Next Web、Creative Bloq、The Fashion Law、Fast Company、BoF、Glossy、ADWEEK 链接：<a href="https://www.pentagram.com/work/mastercard" target="_blank" rel="noreferrer">https://www.pentagram.com/work/mastercard</a> ｜ <a href="https://en.wikipedia.org/wiki/Google_logo" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Google_logo</a> ｜ <a href="https://www.thefashionlaw.com/?s=blanding" target="_blank" rel="noreferrer">https://www.thefashionlaw.com/?s=blanding</a> ｜ <a href="https://www.creativebloq.com/news/twitter-logo-history" target="_blank" rel="noreferrer">https://www.creativebloq.com/news/twitter-logo-history</a> 核实状态：<strong>✅ = 本轮已核对来源；⚠️ = 流传广但未取得一手确认，本文档不当事实使用</strong>（核实日期 2026-09-20）</p></blockquote><h2 id="一、现象的名字-blanding-平淡化" tabindex="-1">一、现象的名字：blanding（平淡化） <a class="header-anchor" href="#一、现象的名字-blanding-平淡化" aria-label="Permalink to &quot;一、现象的名字：blanding（平淡化）&quot;">​</a></h2><p>「现在的 logo 越来越像」这件事在英文里有个专门词：<strong>blanding</strong>（bland + branding）。</p><ul><li>到 <strong>2018 年 12 月</strong>，blanding 已是专业媒体的成熟用词——The Fashion Law 与 Fast Company 在 2018-12-19 前后各自成文使用 ✅</li><li>但<strong>谁最早造这个词、在什么语境下造的，本轮未核实</strong> ⚠️（不要当成有明确发明人的术语）</li><li>一个有意思的旁证：<strong>英文维基没有 Blanding 这个词条</strong>，⟪Blanding⟫ 只是一个人名/地名的消歧义页 ✅。也就是说，一个被行业公开用了近十年的词，还没进百科——它是评论词汇，不是学术词汇。</li></ul><p><strong>趋同不是单向下坡，是一个约八年的完整周期</strong> ✅：</p><table tabindex="0"><thead><tr><th>阶段</th><th>代表性文章/媒体</th><th>年份</th></tr></thead><tbody><tr><td>命名趋同</td><td>The Fashion Law、Fast Company 使用 blanding</td><td>2018</td></tr><tr><td>反趋同第一波</td><td>Business of Fashion《Olding Is the New Blanding》</td><td>2020-11</td></tr><tr><td>反趋同加速</td><td>Glossy《The fall of &#39;blanding&#39;》</td><td>2022-04</td></tr><tr><td>周期收口</td><td>BoF《The End of Blanding?》、ADWEEK《The Continued &#39;Blanding&#39; Trend That Goes Against Industry Research》</td><td>2023</td></tr></tbody></table><p>最后一条 ADWEEK 的标题本身就很关键：<strong>行业研究的数据方向和实际趋势是相反的</strong>——测量结果不支持继续变简，但潮流依旧变简。这正好落回主文档的结论：趋同不在于它更好，而在于它对决策者更&quot;安全&quot;。</p><h2 id="二、案例表-按核实状态分层" tabindex="-1">二、案例表（按核实状态分层） <a class="header-anchor" href="#二、案例表-按核实状态分层" aria-label="Permalink to &quot;二、案例表（按核实状态分层）&quot;">​</a></h2><p><strong>A 层：已核对来源，可直接引用 ✅</strong></p><table tabindex="0"><thead><tr><th>品牌</th><th>时间</th><th>改动内容</th><th>设计方</th><th>来源</th></tr></thead><tbody><tr><td><strong>Gap</strong></td><td>2010-10-04 启用 / <strong>2010-10-11 撤回</strong></td><td>换成 Helvetica 字标、弱化标志性蓝色方框</td><td>未核实 ⚠️</td><td>en.wikipedia ⟪Gap Inc.⟫（含 HuffPost 当年报道链接）</td></tr><tr><td><strong>Starbucks</strong></td><td>2011-01</td><td>去掉环绕 siren 的 &quot;Starbucks Coffee&quot; 字标、放大 siren、改为绿色</td><td>未核实 ⚠️</td><td>en.wikipedia ⟪Starbucks⟫；Reuters 2011-01-05《Starbucks cuts name and &quot;coffee&quot; from logo》</td></tr><tr><td><strong>Airbnb</strong></td><td>2014-07</td><td>发布新 logo「Bélo」，被媒体直接称为 controversial</td><td>DesignStudio 之说未核实 ⚠️</td><td>en.wikipedia ⟪Airbnb⟫；The Next Web 2014-07-16</td></tr><tr><td><strong>Google</strong></td><td>2015-09-01</td><td>字标从衬线（1999 起沿用、Ruth Kedar 设计、基于 Catull 体）换成 Google 自研的几何无衬线 <strong>Product Sans</strong>，色值提亮、去阴影</td><td>内部（in-house）</td><td>en.wikipedia ⟪Google logo⟫</td></tr><tr><td><strong>Mastercard</strong></td><td>2016 符号 / <strong>2019 去字标</strong></td><td>2016 由 Pentagram 纽约重做符号，字标改用无衬线 <strong>FF Mark</strong>、橙成为主色；<strong>2019 干脆去掉 wordmark，只留两个交叠圆</strong></td><td><strong>Pentagram</strong>（Michael Bierut、Luke Hayman；团队成员含 Hamish Smyth、Andrea Trabucco-Campos）✅</td><td>pentagram.com/work/mastercard；en.wikipedia ⟪Mastercard⟫（logo_caption: Logo used since 2019, symbol since 2016）</td></tr><tr><td><strong>Instagram</strong></td><td>2016-05-11</td><td>拟物相机图标换成扁平渐变图形，界面同步极简</td><td>未核实 ⚠️</td><td>It&#39;s Nice That / Time / Marketing Dive 均 2016-05-11</td></tr><tr><td><strong>Balenciaga</strong></td><td>2017-09-29</td><td>发布新字标</td><td>未核实 ⚠️</td><td>Fashionista 2017-09-29</td></tr><tr><td><strong>Burberry</strong></td><td>2018（Tisci 2018-03 上任后数月）</td><td>推出新 logo 与 monogram</td><td><strong>Peter Saville</strong>（英国平面设计师）✅</td><td>en.wikipedia ⟪Burberry⟫（引 GQ 2018-08-02、Nylon）</td></tr><tr><td><strong>Warner Bros.</strong></td><td>2019</td><td>重绘盾牌 logo 并定制专属字体（&quot;R&quot; 的曲率参考重绘的 &quot;B&quot;）</td><td><strong>Pentagram</strong>（Emily Oberman）✅</td><td>pentagram.com/work/warner-bros/story</td></tr><tr><td><strong>Yahoo</strong></td><td>2019-09</td><td>换用新字标，媒体定性为 &quot;21st-century identity&quot;</td><td><strong>Pentagram</strong> ✅（标题级）</td><td>Dezeen 2019-09-26</td></tr><tr><td><strong>Intel</strong></td><td>2020-09</td><td>换标，CMO 定性为面向未来的 rebrand；现用 logo 自 2020 年</td><td>未核实 ⚠️（CMO 表态见 Forbes 2020-09-02）</td><td>en.wikipedia ⟪Intel⟫（logo caption &quot;used since 2020&quot;）</td></tr><tr><td><strong>Meta</strong></td><td>2021-10-28</td><td>改名 Meta，新标为无限环（infinity loop）</td><td>未核实 ⚠️</td><td>about.fb.com 2021-10-28；Dezeen 2021-11-03。<strong>副产品：2022-05 被起诉商标侵权 ✅</strong>（Reuters）</td></tr><tr><td><strong>X（原 Twitter）</strong></td><td>2023-07 启用</td><td>蓝鸟退役换成 &quot;X&quot;，流程延续到 2024-05</td><td>字型来自 Twitter 上公开征集，由用户 <strong>Sawyer Merritt</strong> 提交，基于网络上找到的字体（近似 Unicode Mathematical Double-Struck Capital X）✅</td><td>en.wikipedia ⟪X (social network)⟫；Creative Bloq《The history of the Twitter logo (and the X logo)》</td></tr><tr><td><strong>Johnson &amp; Johnson</strong></td><td>2023-09-14</td><td>更新视觉识别（把沿用多年的手写体换成现代字标）</td><td>未核实 ⚠️</td><td>jnj.com 2023-09-14；NJBIZ / BioPharma Dive 2023-09-15</td></tr></tbody></table><p><strong>B 层：点位流传很广，但本轮未取得一手确认 ⚠️（列为待核实，不作为论据）</strong></p><p>Tropicana 2009 包装改版（常被归为 Arnell Group）、Kia 2021 换标（&quot;KIA&quot; 连笔字型）、GM 2021 换标（小写 gm + 圆角蓝底）、Dropbox 2017 换标（常被归为 Sharp Grotesk 字体）、Céline 2018 去掉字母上的重音符（Hedi Slimane 上任后）、Uber 2018 换标（Uber Move 字体）、<strong>小米 2021 新 logo（原研哉设计、&quot;设计费 200 万人民币&quot;）</strong>。</p><p>其中小米这一条要特别写一句：<strong>中文检索本轮 0 命中</strong>，且 zh.wikipedia ⟪小米⟫ 抓到的页面不含 logo 内容——「200 万」这个数字流传极广，但本文档找不到可引用的一手来源，只能标 ⚠️。这是本库的一条纪律：数字越顺口，越要查。</p><h2 id="三、四个机制-为什么趋同几乎是被-解-出来的-而不是被-选-出来的" tabindex="-1">三、四个机制：为什么趋同几乎是被&quot;解&quot;出来的，而不是被&quot;选&quot;出来的 <a class="header-anchor" href="#三、四个机制-为什么趋同几乎是被-解-出来的-而不是被-选-出来的" aria-label="Permalink to &quot;三、四个机制：为什么趋同几乎是被&quot;解&quot;出来的，而不是被&quot;选&quot;出来的&quot;">​</a></h2><p><strong>1）跨屏适配与小尺寸约束。</strong> 设计方自己的 case study 是最硬的证据：Pentagram 为 Mastercard 做的方案，官方描述目标是 <em>&quot;optimized for use in digital contexts&quot;</em> ✅。一个标要同时活在 16px 的浏览器标签页、40px 的 App 图标、POS 机上、以及几米高的店招上——渐变、细线、细节纹样在最小尺寸直接糊掉，于是它们先死。</p><p><strong>2）品牌资产测量 + 全球一致性。</strong> 同一份 Pentagram 自述里的另一半目标是 <em>&quot;convey simplicity and modernity, while preserving brand equity&quot;</em> ✅。注意这是<strong>两件事同时要求</strong>：看起来像新公司，又要保住已有资产。结果是符号变简洁、但保留可测量的识别锚（Mastercard 就是典型：2016 简化符号，2019 才敢去掉字标——<strong>分两步走，中间隔了三年</strong>）。</p><p><strong>3）法务的拉力：越简单越可控。</strong> 商标越几何化，注册与维权的边界越好界定；反面证据同样清楚——Meta 的无限环 2022 年就被起诉商标侵权 ✅。简单不等于无争议，但复杂图案的维权成本更高。</p><p><strong>4）最小冒犯（主线机制，与主文档同源）。</strong> 这是把「极简主义」和「品牌趋同」焊在一起的那一环：<strong>当一个标识要同时面向 190 个国家的所有年龄、性别、族群、宗教，任何具体的东西都会排除掉一部分人</strong>——某种字体有文化归属，某个图形有宗教联想，某种颜色有政治含义。于是收敛到中性公约数：几何、无衬线、无纹样、无人物。这正是主文档第二节写的最小冒犯，只不过发生在品牌部门：<strong>极简在这里不是美学，是受众风险最小化。</strong></p><p>一句话概括四个机制的合力：<strong>成本要低（少细节好生产）、尺寸要小（少细节好缩放）、法务要稳（少细节好注册）、谁都不能得罪（少细节谁都不冒犯）——四条同向，趋同就是必然解。</strong></p><h2 id="四、代价-省掉的是细节-还是身份" tabindex="-1">四、代价：省掉的是细节，还是身份？ <a class="header-anchor" href="#四、代价-省掉的是细节-还是身份" aria-label="Permalink to &quot;四、代价：省掉的是细节，还是身份？&quot;">​</a></h2><ul><li><strong>可识别性下降，市场会投票。</strong> Gap 是最干净的实验：2010-10-04 启用，<strong>10-11 就撤回，用了不到一周</strong> ✅。这不是审美争论，是市场对&quot;辨识度损失&quot;的直接否决。</li><li><strong>排印单一化。</strong> 本文档能核实来源的案例里，改动方向<strong>无一例外都是无衬线化</strong>（Gap→Helvetica、Mastercard→FF Mark、Google→Product Sans、Burberry→Saville 的无衬线字标）✅。这不是&quot;某些公司都变简洁&quot;，而是<strong>同一个技术解决方案被反复套用</strong>：可缩放、跨语言、易排版。</li><li><strong>最锋利的一刀来自 Gap 这个反例</strong>：公众抗议的对象不是&quot;新标丑&quot;，而是&quot;它不再像 Gap，像任意一家科技公司&quot;。<strong>趋同的代价不是难看，是替换性</strong>——而当 logos 可以互换时，品牌资产的护城河就不再靠标识了。</li><li><strong>必须标明的空白</strong>：本轮<strong>没有</strong>找到&quot;趋同导致品牌价值下降&quot;的量化研究；ADWEEK 2023 那篇标题只说行业研究的方向与趋势相反 ✅，具体数值未取得。别把&quot;看起来在变差&quot;写成&quot;数据显示在变差&quot;。</li></ul><h2 id="五、两条能反着走的路-含一条明确的反面教材" tabindex="-1">五、两条能反着走的路（含一条明确的反面教材） <a class="header-anchor" href="#五、两条能反着走的路-含一条明确的反面教材" aria-label="Permalink to &quot;五、两条能反着走的路（含一条明确的反面教材）&quot;">​</a></h2><p><strong>正例：简化&quot;字&quot;，不简化&quot;符号&quot;。</strong> Mastercard 2019 的主线是<strong>去掉 wordmark、保留并强化符号</strong> ✅。可以省掉的是文字（它本就受语言与尺寸限制），不能省的是那个一眼认得出、且法律上可保护的图形。同一条逻辑，Starbucks 2011 也是去掉环绕文字、放大图形 ✅——两家相隔八年做出同一判断，这比任何评论都有说服力。</p><p><strong>反例：把唯一的辨识点也交给&quot;简单&quot;。</strong> X 的字型来自公开征集、且基于网络上现成的字体（近似某个 Unicode 数学字符）✅。结果是：单字母、极简，但<strong>离开特定字体就不像任何东西</strong>——它把&quot;简化&quot;做到底，同时把&quot;可识别&quot;和&quot;可保护&quot;一起做掉了。这与主文档的判据完全吻合：<strong>省略装饰是增值，省略身份是减值。</strong></p><h2 id="六、判据清单-这个品牌视觉该不该简化" tabindex="-1">六、判据清单：这个品牌视觉该不该简化？ <a class="header-anchor" href="#六、判据清单-这个品牌视觉该不该简化" aria-label="Permalink to &quot;六、判据清单：这个品牌视觉该不该简化？&quot;">​</a></h2><p>可直接用于评审，六问：</p><ol><li><strong>省的是&quot;字&quot;还是&quot;形&quot;？</strong> 字标可省（语言与尺寸约束使然），承载记忆点的图形与配色不可省。Meta 式改名换形、Mastercard 式留形去字，是两种结局。</li><li><strong>缩小测试。</strong> 缩到 16px 还能认出来吗？还是和同行业三家竞品混成一片？认不出，说明省掉的是识别要素，不是装饰。</li><li><strong>互换测试。</strong> 把这个标换到竞品身上，会有人察觉吗？察觉不到 = 这就是趋同本身，而不是&quot;现代的简洁&quot;。</li><li><strong>资产测试。</strong> 改版材料里有没有真实测量（辨识度、联想度、存量认知），还是只有&quot;更现代、更清晰、更友好&quot;这类形容词？Pentagram 的表述里明确保留了 brand equity ✅，&quot;保留资产&quot;应是可检验的约束，不是修辞。</li><li><strong>冒犯测试。</strong> 这次去掉细节，是为了不冒犯任何人，还是为了更好用？如果答案只是前者，得到的就是<strong>一张没有人的脸</strong>——谁都不冒犯，也就谁都不记得。</li><li><strong>撤回成本测试。</strong> 先算清：如果一周内要撤回，代价多大？Gap 的窗口只有 7 天 ✅。当一个改动理论上可以撤回、实际上不可能撤回时，默认应该保留可辨认资产。</li></ol><h2 id="七、一句话" tabindex="-1">七、一句话 <a class="header-anchor" href="#七、一句话" aria-label="Permalink to &quot;七、一句话&quot;">​</a></h2><p><strong>品牌视觉的趋同是一次多约束下的最优化，不是一次审美堕落；但最优化会把&quot;身份&quot;当成可以省略的成本项——而身份恰恰是它唯一该守住的东西。</strong></p><hr><blockquote><p>关键词：极简主义、品牌、logo、趋同、blanding、无衬线、扁平化、最小冒犯、品牌资产、辨识度、重新设计、且慢核实 关联：</p><ul><li><code>topics/design/minimalism-death-of-detail.md</code>：本文档是主文档「最小冒犯」机制在商业视觉上的落地案例集（三条机制：成本、冒犯、去地方性）</li><li><code>topics/design/bauhaus-to-rams.md</code>：几何无衬线化的审美源头在包豪斯与国际风格（&quot;无装饰表面&quot;当初是宣言，现在是默认）</li><li><code>topics/design/less-but-better-engineering.md</code>：本文第六节第 1 问（省的是字还是形）就是工程判据「省略的是装饰还是能力」的品牌版</li><li><code>topics/ai-system-architecture/</code>：模型输出与产品界面的同质化是同一机制的另一种形态（跨场景适配 + 受众风险最小化）</li><li><code>topics/culture/</code>：审美的趋同 → 反趋同周期（2018 blanding → 2020 olding → 2023 复古回潮）是文化钟摆，不是线性演进</li></ul></blockquote><blockquote><p>整理日期：2026-09-20</p></blockquote>',33)])])}const p=o(a,[["render",d]]);export{h as __pageData,p as default};
